#define S(a,b,t) smoothstep(a,b,t)
#define saturate(t) clamp(t,0.,1.)

float easeOutCubic(float t) {
    float tt = (1. - t);
    return 1. - t * t * t;
}

mat2 rot(float r) {
    return mat2(
        cos(r), sin(r),
        -sin(r), cos(r)
    );
}

float rand(vec2 co){
    return fract(sin(dot(co, vec2(12.9898, 78.233))) * 43758.5453);
}

float circle(vec2 p, vec2 center, float size, float width, float s) {
    float d = length(p - center);
    float d1 = smoothstep(d - width * .5 - s, d - width * .5, size);
    float d2 = smoothstep(d + width * .5 + s, d + width * .5, size);
    return d1 * d2;
}

float line(vec2 p, vec2 center, float width, float height, float s) {
    float d = 0.;
    float d1 =
        smoothstep(
            center.x - width * .5 - s,
            center.x - width * .5,
            p.x
        )
        * smoothstep(
            center.x + width * .5 + s,
            center.x + width * .5,
            p.x
        );
    float d2 =
        smoothstep(
            center.y - height * .5 - s,
            center.y - height * .5,
            p.y
        )
        * smoothstep(
            center.y + height * .5 + s,
            center.y + height * .5,
            p.y
        );
    return d1 * d2;
}

vec2 truchetPattern(vec2 id, vec2 uv) {
    float seed = rand(id);
    if(seed < .25) {
       uv = vec2(1. - uv.x, uv.y);
    } else if(seed < .5) {
       uv = vec2(uv.x, 1. - uv.y);
    } else if(seed < .5) {
       uv = 1. - vec2(uv.x, uv.y);
    }
    return uv;
}

// uv: 0~1
vec3 drawPattern(vec2 uv) {
    vec2 uvc = uv - .5;
    vec3 d = vec3(0.);
    vec3 colA = vec3(1., .4, .6);
    vec3 colB = vec3(.1, .4, .6);
    d =
        vec3(0.)
        + line(uv, vec2(.5), .05, .05, .01) * colA
        + line(uv, vec2(0., .5), .15, .075, .025) * colA
        + line(uv, vec2(1., .5), .15, .075, .025) * colA
        + line(uv, vec2(.5, 0.), .075, .15, .025) * colA
        + line(uv, vec2(.5, 1.), .075, .15, .025) * colA
        + line(uv, vec2(.5), 1., .05, .01) * colB
        + line(uv, vec2(.5), .05, .25, .01) * colB
        + line(uvc * rot(45. * 3.14 / 180.) + .5, vec2(.5), .5, .05, .01) * colB
        + line(uvc * rot(135. * 3.14 / 180.) + .5, vec2(.5), 2., .1, .02) * colB

    ;
    return d;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord  - iResolution.xy * .5) / iResolution.xy;

    float t = iTime * .6;

    uv.xy += t * .09;

    uv.x *= (iResolution.x / iResolution.y);

    vec2 rep = vec2(6., 6.);

    vec2 id = floor(uv * rep);
    uv = fract(uv * rep);

    vec3 col = vec3(0.);

    vec2 dotUv = uv;
    float dotPattern = 
        + circle(dotUv, vec2(0., 0.), .01, .075, .05) * 1.
        + circle(dotUv, vec2(0., 1.), .01, .075, .05) * 1.
        + circle(dotUv, vec2(1., 0.), .01, .075, .05) * 1. 
        + circle(dotUv, vec2(1., 1.), .01, .075, .05) * 1. ;
    dotPattern = saturate(dotPattern);

    float period = 1.;
    float timeSeed = rand(vec2(floor(t * period)));

    float r = floor(t) + S(0., .66, mod(t, period));
    float o = mod(floor(rand(vec2(id.x + 1., id.y + 2.)) * 2.), 2.) + 1.;
    uv -= .5;
    uv *= rot(mod(r * 90. * o, 360.) * 3.14 / 180.);
    uv += .5;
    vec2 truchetResult = truchetPattern(id + 0., uv);

    col += drawPattern(truchetResult);

    vec3 dotColor = vec3(.5, .8, .95);    
    col = mix(col, dotColor, dotPattern);

    fragColor = vec4(col, 1.);
}
